use data::*;

macro_rules! implies {
  ($lhs: expr, $rhs: expr) => {
    !$lhs || $rhs
  };
}

macro_rules! impliesL {
  ($lhs: expr, $rhs: expr) => {
    !$lhs | $rhs
  };
}

pub fn isNonNegative(value: i32) -> bool
{
  value >= 0i32
}

pub fn absoluteValue(value: i32) -> i32
{
  if (value < 0i32) {
    -value
  } else {
    value
  }
}
